#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

int fd = open("/dev/i2c-1", O_RDWR);
ioctl(fd, I2C_SLAVE, 0x20);        /* A2..A0 all grounded */

uint8_t out = 0x0F;                /* low nibble low, high nibble released */
write(fd, &out, 1);

/* To read a pin you must first write a 1 to it, which releases it
   to the weak pull-up. A pin you last wrote 0 reads 0 forever. */
uint8_t mask = 0xF0;
write(fd, &mask, 1);
uint8_t in;
read(fd, &in, 1);
